mod pruned;fn main(){let f:serde_json::Value=serde_json::from_str(include_str!("../fixtures.json")).unwrap();let cases:Vec<_>=f.as_array().unwrap().iter().map(pruned::grid_fixture_check).collect();let complete=cases.iter().all(|x|x["rows"].as_array().unwrap().len()==3&&x["rows"].as_array().unwrap().iter().all(|r|r["pass"]==true));println!("{}",serde_json::json!({"schema":"kummer-four-corner-check/v1","cases":cases,"complete":complete,"scientific_execution":false}));assert!(complete);}
